  tools.exec_command({cmd:"sed -n '280,620p' src/components/views/right_panel/RoomSummaryCard.tsx","workdir":"/app","max_output_tokens":14000}),
  tools.exec_command({cmd:"grep -R \"feature_poll_history\" -n src test res 2>/dev/null | head -80","workdir":"/app","max_output_tokens":3000}),
  tools.exec_command({cmd:"grep -R \"useFeatureEnabled\" -n src/components/views/right_panel src/components/views | head -80","workdir":"/app","max_output_tokens":5000}),
  tools.exec_command({cmd:"find test -type f -iname '*RoomSummary*' -o -iname '*Poll*' | head -80","workdir":"/app","max_output_tokens":3000})
]);
